        while x < wx + 16 do
            if F.laneDirty(fld, x, z0, z1, w) then
                local a, b = forward and z0 or z1, forward and z1 or z0
                if pose then
                    local n = { x = x, z = a, yaw = 0 }
                    F.push(p, pose, n)
                    pose = n
                else
                    pose = { x = x, z = a, yaw = 0 }
                end
                local n = { x = x, z = b, yaw = 0 }
                F.push(p, pose, n)
                pose = n
                forward = not forward
            end
            x += w * 0.92
        end
        local t = os.clock()
        while RUNNING and (#p.outbox > 0 or #p.unacked > 0) and os.clock() - t < 1.5 do task.wait() end
        if #p.outbox > 0 and p.seq == seq1 then
            F.stale = true
            LOG("predictor stale")
            return
        end
    else
        while x < wx + 16 do
            if stop() then return end
            if F.laneDirty(fld, x, z0, z1, w) then
                local a, b = forward and z0 or z1, forward and z1 or z0
                if not pose then pose = { x = x, z = a, yaw = 0 }
                elseif not stepTo(x, a) then return end
                if not stepTo(x, b) then return end
                forward = not forward
            end
            x += w * 0.92
        end
    end
    local left = F.tileDust(fld, tx, tz)
    if left < 24 then S.tiles += 1 end
    if F.needDeposit(p) or F.noRoom() then return end
    if (F.got or 0) <= 0 then
        task.wait(0.1)
        return
    end
    F.tries[key] = (F.tries[key] or 0) + 1
    if left >= 24 and F.tries[key] >= 3 then
        F.bad[key] = os.clock() + 120
        F.tries[key] = 0
        LOG("tile left", tx, tz, left)
    end
end
function F.step()
    local p = F.find()
    if not p then
        S.task = __T["Loading dust"]
        task.wait(0.5)
        return
    end
    if (p.broom.reach or 0) > 0 then
        S.task = __T["Needs first person"]
        task.wait(0.5)
        return
    end
    if F.needDeposit(p) then
        if not F.deposit() then task.wait(0.5) end
        return
    end
    if F.noRoom() then
        S.task = __T["Canister full"]
        task.wait(0.5)
        return
    end
    local tx, tz, key = F.nextTile(p.field)
    if not tx then
        S.task = tz and __T["Retrying tiles"] or __T["Moon clean"]
        if M.n("Tank") > 0 and on("f_deposit") then F.deposit() end
        task.wait(1)
        return
    end
    F.sweepTile(p, tx, tz, key)
end
local U = { visitAt = 0, brushAt = 0, failAt = {} }
function U.sheet(k)
