    if bought == 0 then U.fail("upgrades") end
end
function U.visitBrush()
    local pr = U.prompt(function() return Workspace.CentralBuilding.Rooms.ToolShop.ToolRack.Prompt.ToolRackPrompt end)
    if not pr then return U.fail("brush") end
    S.task = __T["Buying brush"]
