        U.closeScreen()
        return U.fail("brush")
    end
    local n0 = S.toastN
    D.Action:FireServer("toolShop", "buy", "brush")
    local msg = U.waitToast(n0)
    LOG("brush", msg, tostring(lp:GetAttribute("Tool")))
