    if msg:find("^Bought") then S.bought += 1 else U.fail("brush") end
end
function U.tick()
    if not IS_MATCH or not M.ready() then return end
    local now = os.clock()
    if on("u_brush") and U.canBuy("brush") and now >= (U.failAt.brush or 0) and now - U.brushAt > 2 then
        U.brushAt = now
        J.push("brush", U.visitBrush)
    end
    if U.dueUpgrade() and now >= (U.failAt.upgrades or 0) and now - U.visitAt > 3 then
        U.visitAt = now
        J.push("upgrades", U.visitUpgrades)
    end
end
function U.skipTutorial()
