function L.shop()
    if not on("l_shop") or lp:GetAttribute("PersistLoaded") ~= true or lp:GetAttribute("LobbyLoaded") ~= true then return end
    if M.n("Persist") < 40 or os.clock() - L.shopAt < 8 then return end
    L.shopAt = os.clock()
    S.task = __T["Buying shard upgrades"]
    local n0 = L.openN
    D.Rm.LobbyShop_Open:FireServer()
