task.spawn(function()
    while RUNNING do
        pcall(function()
            local cash = M.n("Money")
            S.earned = S.earned or 0
            if S.lastCash and cash > S.lastCash then S.earned += cash - S.lastCash end
            S.lastCash = cash
            local mins = math.max((os.clock() - S.t0) / 60, 0.25)
            setText(UI.s1, string.format(__T["Cash %s · +%s/min"], M.cash(cash), M.cash(S.earned / mins)))
            setText(UI.s2, string.format(__T["Canister %s / %s kg"], M.kg(M.n("CanisterKg")), M.kg(M.n("CanisterMaxKg"))))
            setText(UI.s3, string.format(__T["Moon %.1f%% clean · %s"], M.n("MoonCleanPct") + (Workspace:GetAttribute("MoonCleanPct") or 0), tostring(lp:GetAttribute("Tool") or "-")))
            setText(UI.s4, __T["Doing: "] .. S.task)
            setText(UI.s5, os.clock() - S.gmsgAt < 8 and S.gmsg or string.format(__T["Deposits %d · Bought %d"], S.deposits, S.bought))
        end)
        task.wait(0.5)
    end
end)
onClean(function() pcall(function() Library:Unload() end) end)
pcall(function()
    local name, ok, err = SaveManager:GetAutoloadConfig()
    local loaded = false
    if ok and not err then loaded = SaveManager:Load(name) == true end
    if not loaded and isfile and isfile("COMBO_WICK_SWEEP/settings/auto.json") then SaveManager:Load("auto") end
end)
do
    local pending = false
    local function queue()
        if pending or not RUNNING then return end
        pending = true
        task.delay(1.5, function() pending = false; if RUNNING then pcall(function() if not SaveManager.Library.Unloaded then SaveManager:Save("auto") end end) end end)
    end
    local function skip(k) k = tostring(k); return k == "f_pause" or k == "MenuKeybind" or k:find("^ThemeManager") or k:find("^SaveManager") or k:find("Color") or k == "FeedbackMsg" or k == "FeedbackType" end
    task.delay(2, function()
        for k, t in pairs(Toggles) do if not skip(k) then pcall(function() local prev = t.Changed t:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
        for k, o in pairs(Opt) do if not skip(k) then pcall(function() local prev = o.Changed o:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
    end)
end
setText(UI.exec, __T["Checking your executor..."])
task.spawn(function()
    local miss = {}
    for _, n in ipairs(getgenv().CW_NEEDS or {}) do if not CAP.cap(n) then miss[#miss + 1] = n end end
    if #miss > 0 then
        setText(UI.exec, '<font color="#ff6b6b">' .. __T["Missing: "] .. table.concat(miss, ", ") .. '</font>')
        notify(__T["Some features don't work on your executor. See Quick Start in the Suggestions tab."])
    else
        setText(UI.exec, '<font color="#7ED957">' .. __T["Executor check: all features supported"] .. '</font>')
    end
    LOG("exec check", "missing=" .. table.concat(miss, ","))
end)
